'use client';
import { useMemo, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { spring, springToLinear, useStudioMotion, type SpringToken } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { axis: 'horizontal' | 'vertical'; spring: SpringToken; perspective: number; tilt: number };

const STEPS = [
  { n: '01', kicker: 'Listen', title: 'Brief', body: 'One working session to agree what the page should make people feel, and what it must never do.', tone: 'paper' },
  { n: '02', kicker: 'Sketch', title: 'Prototype', body: 'Motion is designed in the browser from day one: timing, easing and interruption included.', tone: 'ink' },
  { n: '03', kicker: 'Refine', title: 'Polish', body: 'Reduced-motion paths, focus order and frame budgets are tuned alongside the visuals.', tone: 'signal' },
  { n: '04', kicker: 'Release', title: 'Ship', body: 'Recipes land as portable folders. Copy, paste, and theme with custom properties.', tone: 'green' },
] as const;
const COUNT = STEPS.length;
const wrap = (n: number) => ((n % COUNT) + COUNT) % COUNT;

export default function CssCubeCarousel({ params }: EffectProps<Params>) {
  const { reduced, scale } = useStudioMotion();
  /** Unbounded quarter-turn counter, so 4 → 1 keeps turning the same way instead of unwinding. */
  const [turn, setTurn] = useState(0);
  const [done, setDone] = useState<readonly boolean[]>(() => STEPS.map(() => false));
  const active = wrap(turn);
  const vertical = params.axis === 'vertical';
  const motion = useMemo(() => springToLinear(spring[params.spring] ?? spring.settle, 40), [params.spring]);

  const go = (delta: number) => setTurn((t) => t + delta);
  const goTo = (index: number) => {
    // shortest way round: -2..1 quarter turns
    const delta = ((index - active + COUNT + 2) % COUNT) - 2;
    if (delta !== 0) go(delta);
  };
  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    if (e.altKey || e.ctrlKey || e.metaKey) return;
    const next = vertical ? ['ArrowDown', 'ArrowRight'] : ['ArrowRight', 'ArrowDown'];
    const prev = vertical ? ['ArrowUp', 'ArrowLeft'] : ['ArrowLeft', 'ArrowUp'];
    if (next.includes(e.key)) { e.preventDefault(); go(1); }
    else if (prev.includes(e.key)) { e.preventDefault(); go(-1); }
    else if (e.key === 'Home') { e.preventDefault(); goTo(0); }
    else if (e.key === 'End') { e.preventDefault(); goTo(COUNT - 1); }
  };

  const tilt = reduced ? 0 : params.tilt;
  const depth = vertical ? 'var(--h)' : 'var(--w)';
  const prismTransform = vertical
    ? `translateZ(calc(${depth} / -2)) rotateY(${tilt}deg) rotateX(${turn * 90}deg)`
    : `translateZ(calc(${depth} / -2)) rotateX(${-tilt}deg) rotateY(${-turn * 90}deg)`;
  const faceTransform = (i: number) => (vertical ? `rotateX(${-i * 90}deg)` : `rotateY(${i * 90}deg)`) + ` translateZ(calc(${depth} / 2))`;

  return (
    <section
      className={styles.root}
      aria-roledescription="carousel"
      aria-label="How a Studio³ project runs (sample content)"
      data-reduced={reduced || undefined}
      onKeyDown={onKeyDown}
      style={{ '--persp': `${params.perspective}px`, '--dur': `${Math.round(motion.duration * scale.duration)}ms`, '--ease': motion.easing } as CSSProperties}
    >
      <div className={styles.scene}>
        <div className={styles.prism} style={{ transform: prismTransform }}>
          {STEPS.map((s, i) => (
            <article
              key={s.n}
              className={styles.face}
              data-tone={s.tone}
              data-active={i === active || undefined}
              role="group"
              aria-roledescription="slide"
              aria-label={`${i + 1} of ${COUNT}: ${s.title}`}
              inert={i !== active}
              style={{ transform: faceTransform(i) }}
            >
              <p className={styles.kicker}><span>{s.kicker}</span><span aria-hidden="true">{s.n} / 04</span></p>
              <h3 className={styles.title}>{s.title}</h3>
              <p className={styles.body}>{s.body}</p>
              <button
                type="button"
                className={styles.mark}
                aria-pressed={done[i]}
                onClick={() => setDone((d) => d.map((v, j) => (j === i ? !v : v)))}
              >
                <span className={styles.check} aria-hidden="true" />
                {done[i] ? 'Marked done' : 'Mark as done'}
              </button>
            </article>
          ))}
        </div>
      </div>

      <div className={styles.controls}>
        <button type="button" className={styles.arrow} onClick={() => go(-1)} aria-label="Previous step">
          <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M10 3 5 8l5 5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></svg>
        </button>
        <ol className={styles.dots}>
          {STEPS.map((s, i) => (
            <li key={s.n}>
              <button type="button" className={styles.dot} aria-label={`Go to step ${i + 1}: ${s.title}${done[i] ? ' (done)' : ''}`} aria-current={i === active ? 'step' : undefined} data-done={done[i] || undefined} onClick={() => goTo(i)}>
                <span aria-hidden="true" />
              </button>
            </li>
          ))}
        </ol>
        <button type="button" className={styles.arrow} onClick={() => go(1)} aria-label="Next step">
          <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="m6 3 5 5-5 5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></svg>
        </button>
      </div>
      <p className={styles.srOnly} aria-live="polite">Step {active + 1} of {COUNT}: {STEPS[active].title}</p>
    </section>
  );
}

.root {
  --w: clamp(230px, 58cqi, 470px);
  --h: clamp(230px, 36cqi, 280px);
  display: grid;
  justify-items: center;
  gap: 26px;
  width: 100%;
  padding: 40px 16px 24px;
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
}
.scene {
  width: var(--w);
  height: var(--h);
  perspective: var(--persp, 1100px);
}
.prism {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform var(--dur, 600ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.face {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: clamp(16px, 4.2cqi, 26px);
  border-radius: var(--s3-radius-s, 4px);
  border: 1px solid var(--s3-line, #11110f24);
  backface-visibility: hidden;
  overflow: hidden;
  background: var(--face-bg);
  color: var(--face-ink);
}
.face[data-tone='paper'] { --face-bg: #f3f0e8; --face-ink: #11110f; --face-soft: #11110f99; }
.face[data-tone='ink'] { --face-bg: #1b1b18; --face-ink: #f3f0e8; --face-soft: #f3f0e8a6; }
.face[data-tone='signal'] { --face-bg: #e03a0c; --face-ink: #fffaf2; --face-soft: #fffaf2d9; }
.face[data-tone='green'] { --face-bg: #0f6b57; --face-ink: #f3f0e8; --face-soft: #f3f0e8d1; }
/* Shading: faces turned away from the viewer fall into shadow, which sells the solid. */
.face::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, #0b0b09 0%, #0b0b0999 100%);
  opacity: 0.42;
  pointer-events: none;
  transition: opacity var(--dur, 600ms) var(--s3-ease-standard, cubic-bezier(0.2, 0, 0, 1));
}
.face[data-active]::after { opacity: 0; }
.kicker {
  display: flex;
  justify-content: space-between;
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--face-soft);
}
.title {
  margin: auto 0 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(2.1rem, 9cqi, 4rem);
  font-weight: 700;
  line-height: 0.92;
  letter-spacing: -0.04em;
}
.body {
  margin: 10px 0 14px;
  max-width: 38ch;
  font-size: clamp(0.8125rem, 2.2cqi, 0.9375rem);
  line-height: 1.4;
  color: var(--face-soft);
}
.mark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  align-self: flex-start;
  min-height: 32px;
  padding: 4px 12px 4px 8px;
  border: 1px solid currentColor;
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.8125rem;
  cursor: pointer;
}
.mark:focus-visible, .arrow:focus-visible, .dot:focus-visible {
  outline: 2px solid var(--s3-focus, #1d4ed8);
  outline-offset: 2px;
}
.face .mark:focus-visible { outline-color: currentColor; }
.check {
  width: 14px;
  height: 14px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  transition: box-shadow var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease);
}
.mark[aria-pressed='true'] .check { box-shadow: inset 0 0 0 3px var(--face-bg), inset 0 0 0 8px currentColor; }

.controls { display: flex; align-items: center; gap: 10px; }
.arrow {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background-color var(--s3-duration-fast, 160ms), color var(--s3-duration-fast, 160ms);
}
.arrow:hover { background: var(--s3-ink, #11110f); color: var(--s3-surface, #fbf9f4); }
.arrow:active { transform: scale(0.96); }
.dots { display: flex; gap: 2px; margin: 0; padding: 0; list-style: none; }
.dot {
  display: grid;
  place-items: center;
  width: 28px;
  height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  cursor: pointer;
}
.dot span {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  border: 1.5px solid currentColor;
  transition: width var(--s3-duration-base, 240ms) var(--s3-ease-emphasized, ease), background-color var(--s3-duration-fast, 160ms);
}
.dot[data-done] span { background: currentColor; }
.dot[aria-current] span { width: 22px; background: var(--s3-accent, #e03a0c); border-color: var(--s3-accent, #e03a0c); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* Reduced motion: no turning. Faces swap with a short opacity fade. */
.root[data-reduced] .prism { transition: none; }
.root[data-reduced] .face { opacity: 0; transition: opacity 160ms linear; }
.root[data-reduced] .face[data-active] { opacity: 1; }
.root[data-reduced] .face::after { transition: none; }
@media (prefers-reduced-motion: reduce) {
  .prism { transition: none; }
  .face::after, .dot span, .arrow, .check { transition: none; }
}
